export default function collectImagePages({records,offset,previousState}) {
  if (!Array.isArray(records)) throw new Error('Missing Airtable records');
  const state=previousState ?? {records:[],seen:[]};
  if (!Array.isArray(state.records)||!Array.isArray(state.seen)) throw new Error('Invalid pagination state');
  if (offset!==null && (typeof offset!=='string'||!offset||state.seen.includes(offset))) throw new Error('Invalid or repeated Airtable offset');
  return {state:{records:[...state.records,...records],seen:offset===null?state.seen:[...state.seen,offset]},offset:offset??"unused",more:offset!==null};
}
